 string ScanKey(string kind,string folder){return kind+"|"+Path.GetFullPath(folder).TrimEnd(Path.DirectorySeparatorChar).ToUpperInvariant();}
 Dictionary<string,object> ReadScans(){try{var data=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(scanCachePath));if(Convert.ToInt32(data["SchemaVersion"])==1)return (Dictionary<string,object>)data["Scans"];}catch{}return new Dictionary<string,object>();}
 void RememberScan(string kind,string folder,Dictionary<string,object>[] rows,bool merge){if(rows.Length==0&&merge)return;try{var scans=ReadScans();string key=ScanKey(kind,folder);var saved=new List<Dictionary<string,object>>();if(merge&&scans.ContainsKey(key)){var old=(Dictionary<string,object>)scans[key];saved.AddRange(json.Deserialize<Dictionary<string,object>[]>(json.Serialize(old["Rows"])));}foreach(var row in rows){saved.RemoveAll(r=>Get(r,"Id")==Get(row,"Id")&&merge);var copy=new Dictionary<string,object>(row);copy["ScannedAt"]=DateTime.Now.ToString("g");saved.Add(copy);}scans[key]=new Dictionary<string,object>{{"SavedAt",DateTime.Now.ToString("g")},{"Rows",saved}};WriteSettings(scanCachePath,new Dictionary<string,object>{{"SchemaVersion",1},{"Scans",scans}});}catch(Exception ex){status.Text="Could not remember scan results: "+ReadableMessage(ex.Message);}}
 Dictionary<string,object>[] SavedScan(string kind,string folder,out string scannedAt){scannedAt="";try{object record;var scans=ReadScans();if(!scans.TryGetValue(ScanKey(kind,folder),out record))return null;var saved=(Dictionary<string,object>)record;scannedAt=Get(saved,"SavedAt");return json.Deserialize<Dictionary<string,object>[]>(json.Serialize(saved["Rows"]));}catch{return null;}}
 bool RestoreMediaScan(){if(string.IsNullOrWhiteSpace(mediaFolder.Text))return false;string when;var saved=SavedScan("Media",mediaFolder.Text,out when);if(saved==null)return false;foreach(var row in mediaRows){var match=saved.FirstOrDefault(r=>Get(r,"Kind")==Get(row,"Kind")&&Get(r,"Name")==Get(row,"Name")&&Get(r,"Set")==Get(row,"Set"));if(match!=null)foreach(string field in new[]{"Status","File","Match"})row[field]=Get(match,field);}RefreshMedia();mediaSummary.Text="Last scanned: "+when+". Showing saved results for this folder. Scan again after changing files. Installation always checks the files again.";return true;}
 bool RestoreGameScan(){string when;var saved=SavedScan("Games",gameFolder.Text,out when);if(saved==null)return false;ApplyGameInventory(saved);gameSummary.Text+=" Last scanned: "+when+". Showing saved results; scan again after changing files.";return true;}
 void RestorePackageScans(){foreach(string kind in new[]{"Packages","UserPackages"}){string when;var saved=SavedScan(kind,kind=="Packages"?root:userPackagesFolder,out when);if(saved==null)continue;foreach(var row in saved){var current=packages.FirstOrDefault(p=>p.Id==Get(row,"Id"));if(current==null||current.Version!=Get(row,"Version")||current.Url!=Get(row,"Url")&&row.ContainsKey("Url"))continue;var copy=new Dictionary<string,object>(row);copy["Details"]="Last scanned: "+Get(row,"ScannedAt")+". Saved result. "+Get(row,"Details");ApplyRows(new[]{copy});}}}
