 void AddSettings(){var panel=new StackPanel{Margin=new Thickness(22)};panel.Children.Add(new TextBlock{Text="Save & load configuration",FontSize=23,FontWeight=FontWeights.Bold});panel.Children.Add(new TextBlock{Text="Your current choices are saved automatically. Save a settings file to keep a named configuration, or load one to restore previous choices. You can also load existing installer settings.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,14,0,18),MaxWidth=850,HorizontalAlignment=HorizontalAlignment.Left});var profileBar=new WrapPanel();var saveSettings=Button("Save settings…",delegate{SaveSettingsFile();});var loadSettings=Button("Load settings…",async delegate{await LoadSettingsFile();});profileBar.Children.Add(saveSettings);profileBar.Children.Add(loadSettings);panel.Children.Add(profileBar);operationButtons.Add(saveSettings);operationButtons.Add(loadSettings);panel.Children.Add(new TextBlock{Text="After loading, review your choices in the other tabs. Use Review & Install to validate and apply them to the installer.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,18,0,0)});var setupSection=new GroupBox{Header="Existing installer setup",Margin=new Thickness(0,28,0,0),Padding=new Thickness(14),HorizontalAlignment=HorizontalAlignment.Left};var setupPanel=new StackPanel();setupPanel.Children.Add(new TextBlock{Text="Open the original installer setup to review its configuration and start installation.",TextWrapping=TextWrapping.Wrap,MaxWidth=750,Margin=new Thickness(0,0,0,10)});setupPanel.Children.Add(Button("Open existing setup",delegate{LaunchSetup();}));setupSection.Content=setupPanel;panel.Children.Add(setupSection);var helpSection=new GroupBox{Header="Help & documentation",Margin=new Thickness(0,20,0,0),Padding=new Thickness(14),HorizontalAlignment=HorizontalAlignment.Left};helpSection.Content=Button("Open GUI user guide",delegate{string guide=Path.Combine(root,"docs","gui","user-guide.html");if(!File.Exists(guide)){status.Text="The GUI user