 Dictionary<string,object> ImageMetadata(string path,bool archive){
 if(!archive)return json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(path,"hstwb-image.json")));
 using(var zip=ZipFile.OpenRead(path)){var entries=zip.Entries.Where(e=>e.Name.Equals("hstwb-image.json",StringComparison.OrdinalIgnoreCase)).ToArray();if(entries.Length!=1)throw new Exception("Template must contain one hstwb-image.json.");using(var reader=new StreamReader(entries[0].Open()))return json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());}
 }
 long ImageBytes(Dictionary<string,object> data){object value;if(!data.TryGetValue("harddrives",out value)||!(value is System.Collections.IList)||((System.Collections.IList)value).Count==0)throw new Exception("Image has no harddrives.");long total=0;foreach(Dictionary<string,object> drive in (System.Collections.IEnumerable)value){if(Get(drive,"type")=="hdf"){long size;if(!long.TryParse(Get(drive,"size"),out size)||size<=0)throw new Exception("Invalid harddrive size.");total=checked(total+size);}}return total;}
 void CapturePreview(string filename,int tabIndex){tabs.SelectedIndex=tabIndex;var visual=(FrameworkElement)Content;visual.Measure(new Size(1180,780));visual.Arrange(new Rect(0,0,1180,780));visual.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(1180,780,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(root,".output","desktop",filename)))encoder.Save(stream);}
 void TestScanMemory(){string cache=Path.Combine(root,".output","desktop","test-scan-memory.json");if(File.Exists(cache))File.Delete(cache);string previousCache=scanCachePath;scanCachePath=cache;try{string folder=Path.Combine(root,".output","desktop","test-media");var row=new Dictionary<string,object>{{"Kind","Kickstart"},{"Name","Remembered ROM"},{"Set","Test"},{"Status","Detected"},{"Match","MD5"},{"File",Path.Combine(folder,"test.rom")}};RememberScan("Media",folder,new[]{row},false);var reopened=new Desktop(root);reopened.loading=true;reopened.scanCachePath=cache;reopened.mediaFolder.Text=folder;reopened.mediaRows=new List<Dictionary<string,object>>{new Dictionary<string,object>(row)};reopened.mediaRows[0]["Status"]="Not scanned";if(!reopened.RestoreMediaScan()||Get(reopened.mediaRows[0],"Status")!="Detected"||!reopened.mediaSummary.Text.Contains("Last scanned:"))throw new Exception("Scan results did not survive reopening.");string when;if(reopened.SavedScan("Media",folder+"-different",out when)!=null)throw new Exception("Scan results leaked across folders.");var one=new Dictionary<string,object>{{"Id","one"},{"Version","1.0"}};var two=new Dictionary<string,object>{{"Id","two"},{"Version","2.0"}};RememberScan("Packages",root,new[]{one},true);RememberScan("Packages",root,new[]{two},true);one["Version"]="3.0";RememberScan("Packages",root,new[]{one},true);var merged=reopened.SavedScan("Packages",root,out when);if(merged.Length!=2||Get(merged.Single(r=>Get(r,"Id")=="one"),"Version")!="3.0")throw new Exception("Incremental scan cache lost entries.");File.WriteAllText(cache,"broken json");if(reopened.SavedScan("Media",folder,out when)!=null)throw new Exception("Corrupt scan cache accepted.");}finally{scanCachePath=previousCache;}}
 void TestCompactRows(){foreach(string category in new[]{"Packages","User Packages"}){var tab=tabs.Items.Cast<TabItem>().First(t=>(string)t.Header==category);var grid=((DockPanel)tab.Content).Children.OfType<DataGrid>().Single();if(grid.RowHeight!=36||grid.ColumnHeaderHeight!=36)throw new Exception("Package table sizing regressed.");}var first=packages.First(p=>p.Category=="Packages");ApplyRows(new[]{new Dictionary<string,object>{{"Id",first.Id},{"Status","Check unavailable"},{"Details","Invoke-WebRequest: API rate limit exceeded\r\nAt fake.ps1:10\r\nCategoryInfo: diagnostic"}}});if(!first.Details.StartsWith("GitHub request limit")||first.Details.Contains("\n")||first.Details.Contains("CategoryInfo"))throw new Exception("Details leaked raw diagnostics.");theme.SelectedIndex=0;brightness.SelectedIndex=0;ApplyTheme();CapturePreview("package-screen.png",2);}
 void TestSettingsAndSorting(){loading=true;if(!OsOptions().Contains("Amiga OS 3.2.1")||!OsOptions().Contains("Amiga OS 3.2.3"))throw new Exception("Missing OS target release.");osSet="Amiga OS 3.2";targetVersion="3.2.3";SetMediaChoices();if(Convert.ToString(osChoice.SelectedItem)!="Amiga OS 3.2.3")throw new Exception("OS target not selected.");var first=packages.First(p=>p.Category=="User Packages");first.Selected=true;approvals[first.Id]=ReviewFingerprint(first);var snapshot=json.Deserialize<Dictionary<string,object>>(json.Serialize(SettingsSnapshot()));string file=Path.Combine(root,".output","desktop","settings-roundtrip.json");WriteSettings(file,snapshot);WriteSettings(file,snapshot);osSet="";targetVersion="";first.Selected=false;approvals.Clear();ApplySettingsData(json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file)));if(userPackagesFolder!=Convert.ToString(snapshot["UserPackagesFolder"])||gameFolder.Text!=Convert.ToString(snapshot["GamePacksFolder"])||targetVersion!="3.2.3"||!first.Selected||first.ReviewDecision!="Approved for installation")throw new Exception("Settings roundtrip lost target, selection or approval.");foreach(string category in new[]{"Packages","User Packages"}){var tab=tabs.Items.Cast<TabItem>().First(t=>(string)t.Header==category);var grid=((DockPanel)tab.Content).Children.OfType<DataGrid>().Single();foreach(var column in grid.Columns)if(column.Header.ToString()!="Actions"&&string.IsNullOrEmpty(column.SortMemberPath))throw new Exception("Unsortable column: "+column.Header);var view=(ListCollectionView)grid.ItemsSource;view.SortDescriptions.Clear();view.SortDescriptions.Add(new SortDescription("Name",ListSortDirection.Descending));var names=view.Cast<Package>().Select(p=>p.Name).ToArray();if(!names.SequenceEqual(names.OrderByDescending(n=>n,StringComparer.CurrentCulture)))throw new Exception("Package name sorting failed.");view.SortDescriptions.Clear();}var invalid=new Dictionary<string,object>(snapshot);invalid["ImageMode"]=99;bool rejected=false;try{ApplySettingsData(invalid);}catch{rejected=true;}if(!rejected||targetVersion!="3.2.3")throw new Exception("Invalid settings changed draft.");}
 void TestSelectorsAndVersions(){loading=true;mediaRows=Bridge("MediaCatalog",null).ToList();SetMediaChoices();if(osChoice.Items.Count==0||kickstartChoice.Items.Count==0)throw new Exception("Media selectors are empty.");osChoice.SelectedIndex=0;kickstartChoice.SelectedIndex=0;string wantedOs=osSet,wantedRom=kickstartSet;SetMediaChoices();RefreshMedia();if(osSet!=wantedOs||kickstartSet!=wantedRom||Convert.ToString(osChoice.SelectedItem)!=wantedOs||Convert.ToString(kickstartChoice.SelectedItem)!=wantedRom)throw new Exception("Media selectors lost saved choices.");if(mediaGrid.Items.Count!=mediaRows.Count)throw new Exception("Media selectors hid missing or other media.");ApplyRows(new[]{new Dictionary<string,object>{{"Id","test/version"},{"Category","User Packages"},{"Name","Version refresh test"},{"Version","1.0"},{"Status","Current"}}});ApplyRows(new[]{new Dictionary<string,object>{{"Id","test/version"},{"Version","2.0"},{"Available","2.0"},{"Status","Updated"}}});var item=packages.Single(p=>p.Id=="test/version");if(item.Version!="2.0"||item.Available!="2.0")throw new Exception("Updated version not refreshed.");packages.Remove(item);var emulators=Bridge("Emulators",null);foreach(var row in emulators)if(string.IsNullOrEmpty(Get(row,"Name"))||!File.Exists(Get(row,"Path")))throw new Exception("Invalid emulator discovery.");}
 void TestImageChoices(){loading=true;if(imageChoices.Count==0)throw new Exception("No image templates loaded.");var usable=imageChoices.Where(c=>c.Error==null).ToArray();if(usable.Length==0)throw new Exception("No readable image template.");var fixture=Path.Combine(root,".output","desktop","image-validation-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);var emulator=Path.Combine(fixture,"winuae.exe");File.WriteAllText(emulator,"");emulatorFile.Text=emulator;imageMode.SelectedIndex=0;imageTemplate.SelectedItem=usable[0];imageFolder.Text=fixture;if(!ValidateImageChoices().Any(r=>r.Contains("requires approval")))throw new Exception("Nonempty destination accepted.");approvedImageFolder=Path.GetFullPath(fixture);if(!ValidateImageChoices().Single().Contains("passed basic"))throw new Exception("Approved nonempty folder blocked.");imageFolder.Text=Path.Combine(fixture,"new-image");if(!ValidateImageChoices().Single().Contains("passed basic"))throw new Exception("New image choices failed.");imageMode.SelectedIndex=1;imageFolder.Text=fixture;File.WriteAllText(Path.Combine(fixture,"hstwb-image.json"),"{\"name\":\"Synthetic\",\"harddrives\":[{\"type\":\"hdf\",\"path\":\"disk.hdf\",\"size\":512}]}");if(!ValidateImageChoices().Any(r=>r.Contains("Missing image drive")))throw new Exception("Missing disk accepted.");File.WriteAllText(Path.Combine(fixture,"disk.hdf"),"");if(!ValidateImageChoices().Single().Contains("passed basic"))throw new Exception("Existing image validation failed.");File.WriteAllText(Path.Combine(fixture,"hstwb-image.json"),"{\"harddrives\":[{\"type\":\"hdf\",\"path\":\"../outside.hdf\",\"size\":512}]}");if(!ValidateImageChoices().Any(r=>r.Contains("outside its folder")))throw new Exception("Escaping drive path accepted.");imageMode.SelectedIndex=0;imageFolder.Text="";emulatorFile.Text="";imageValidation.Text="Image validation checks passed.";}
