 panel.Children.Add(new TextBlock{Text="Image source"});imageMode.ItemsSource=new[]{"New image for each installation","Inspect an existing image folder"};imageMode.SelectedIndex=0;imageMode.Margin=new Thickness(0,6,0,12);AutomationProperties.SetName(imageMode,"Image source");panel.Children.Add(imageMode);
