 List<string> ValidateImageChoices(bool askApproval=false){var result=new List<string>();try{
 bool existing=imageMode.SelectedIndex==1;Dictionary<string,object> data=null;
 if(existing){if(!Directory.Exists(imageFolder.Text))result.Add("Choose an existing image folder.");else data=ImageMetadata(imageFolder.Text,false);}else{var choice=imageTemplate.SelectedItem as ImageChoice;if(choice==null)result.Add("Choose an image template.");else{data=ImageMetadata(choice.Path,true);ImageBytes(data);}if(string.IsNullOrWhiteSpace(imageFolder.Text))result.Add("Choose a destination folder.");else{var destination=Path.GetFullPath(imageFolder.Text);if(File.Exists(destination))result.Add("Destination is a file. Choose a folder.");else if(Directory.Exists(destination)&&Directory.EnumerateFileSystemEntries(destination).Any()&&!destination.Equals(approvedImageFolder,StringComparison.OrdinalIgnoreCase)){if(askApproval&&MessageBox.Show(this,"This image folder already contains files:\n\n"+destination+"\n\nUse this folder for the image draft? Validation will not delete or overwrite its files. Image creation remains a separate step in setup.","Use nonempty image folder?",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes)approvedImageFolder=destination;else result.Add("Nonempty image folder requires approval before continuing.");}var parent=Directory.Exists(destination)?destination:Path.GetDirectoryName(destination);if(!Directory.Exists(parent))result.Add("Create or choose the destination parent folder first.");}}
 if(data!=null){ImageBytes(data);if(existing){foreach(Dictionary<string,object> drive in (System.Collections.IEnumerable)data["harddrives"]){string relative=Get(drive,"path");string full=Path.GetFullPath(Path.Combine(imageFolder.Text,relative));string imageRoot=Path.GetFullPath(imageFolder.Text).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(Path.IsPathRooted(relative)||!full.StartsWith(imageRoot,StringComparison.OrdinalIgnoreCase)){result.Add("Image contains a drive path outside its folder; review in existing setup.");continue;}if(!File.Exists(full)&&!Directory.Exists(full))result.Add("Missing image drive: "+relative);}}}
 string exe=Path.GetFileName(emulatorFile.Text);if(!File.Exists(emulatorFile.Text))result.Add("Choose an existing emulator executable.");else if(!new[]{"winuae.exe","winuae64.exe","fs-uae.exe"}.Contains(exe,StringComparer.OrdinalIgnoreCase))result.Add("Select WinUAE or FS-UAE. Other executables are not supported by this screen.");
 }catch(Exception ex){result.Add("Cannot validate image: "+ex.Message);}if(result.Count==0)result.Add("Image and emulator paths passed basic validation. Use Review & Install to validate media and run installation into a fresh image.");return result;}
