 void OpenLink(object sender,RoutedEventArgs e){var url=(string)((Button)sender).Tag;Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.Scheme!="https"){MessageBox.Show(this,"No verified source webpage is configured for this component.");return;}try{Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(this,ex.Message);}}
