 async Task Update(bool all,string category){var ids=packages.Where(p=>p.Category==category && (all?(category=="Packages"?!string.IsNullOrEmpty(p.Version)&&p.Version!="Not downloaded":System.IO.Directory.Exists(p.Directory)):p.Selected)).Select(p=>p.Id).ToArray();if(ids.Length==0){status.Text="Select at least one package or application.";return;}if(MessageBox.Show(this,category=="Packages"?"Download saved stable releases for "+ids.Length+" packages? Matching local versions will be skipped. Use Check for updates first if you want to refresh the release list.":"Check "+ids.Length+" components and update compatible releases in the PC library? The existing updater preserves backups. Amiga images are not changed.","Update local library",MessageBoxButton.OKCancel)!=MessageBoxResult.OK)return;await Run(category=="Packages"?"DownloadPackages":"Update",ids);}
 string InstallerValidationText(Dictionary<string,object> row){if(Convert.ToBoolean(row["Valid"]))return "Configuration checks passed for Install mode. Ready to run installation or apply settings.\n\nInstaller packages: "+string.Join(", ",RowStrings(row,"PackageNames"))+"\nUser-package bundles: "+string.Join(", ",RowStrings(row,"UserPackageNames"))+"\n\n"+string.Join("\n",RowStrings(row,"Notes"));var issues=((System.Collections.IEnumerable)row["Issues"]).Cast<Dictionary<string,object>>().Select(issue=>Get(issue,"Area")+": "+ReadableMessage(Get(issue,"Message")));return "Resolve these items before applying:\n\n"+string.Join("\n",issues);}
 void TestGamesTab(){ApplyGameInventory(Bridge("GamePacks",new[]{gameFolder.Text}));if(gameGrid.Items.Count!=gamePacks.Count)throw new Exception("Game pack inventory not shown.");var bundle=packages.Single(p=>p.Id=="gamepack/whdload-packs");gameBundleCheck.IsChecked=true;if(!bundle.Selected||!((string[])SettingsSnapshot()["Selected"]).Contains(bundle.Id))throw new Exception("Game bundle checkbox not persisted.");gameBundleCheck.IsChecked=false;if(bundle.Selected)throw new Exception("Game bundle checkbox did not clear.");CapturePreview("games-screen.png",4);}
 void TestNativeReview(){string settingsFile=Path.Combine(root,"settings","hstwb-installer-settings.ini");string before=File.Exists(settingsFile)?Convert.ToBase64String(File.ReadAllBytes(settingsFile)):"absent";var draft=json.Serialize(new{OsSet="",TargetVersion="",KickstartSet="",MediaFolder="",ImageMode=0,ImageFolder="",EmulatorFile="",Selected=new string[0]});var row=Bridge("ValidateInstaller",new[]{draft}).Single();if(Convert.ToBoolean(row["Valid"]))throw new Exception("Empty native draft accepted.");installerValidation.Text=InstallerValidationText(row);if(!installerValidation.Text.Contains("AmigaOS:")||!installerValidation.Text.Contains("Image:"))throw new Exception("Native validation issues not displayed.");string after=File.Exists(settingsFile)?Convert.ToBase64String(File.ReadAllBytes(settingsFile)):"absent";if(before!=after)throw new Exception("Native validation wrote installer settings.");CapturePreview("review-screen.png",tabs.Items.Count-1);}
 string InstallerDraftJson(){if(!string.IsNullOrWhiteSpace(imageFolder.Text)&&(plannedImageFolder==""||!string.Equals(Path.GetDirectoryName(plannedImageFolder),Path.GetFullPath(imageFolder.Text).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase)))plannedImageFolder=Path.Combine(Path.GetFullPath(imageFolder.Text),"Install-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8));var snapshot=SettingsSnapshot();return json.Serialize(new{UserPackagesFolder=userPackagesFolder,GamePacksFolder=gameFolder.Text,OsSet=osSet,TargetVersion=targetVersion,KickstartSet=kickstartSet,MediaFolder=mediaFolder.Text,CreateNewImage=true,NewImageFolder=plannedImageFolder,ImageTemplate=imageTemplate.SelectedItem==null?"":((ImageChoice)imageTemplate.SelectedItem).Path,ImageMode=imageMode.SelectedIndex,ImageFolder=imageFolder.Text,EmulatorFile=emulatorFile.Text,Selected=((string[])snapshot["Selected"]).OrderBy(id=>id).ToArray()});}
 string[] RowStrings(Dictionary<string,object> row,string key){if(!row.ContainsKey(key)||row[key]==null)return new string[0];var values=row[key] as System.Collections.IEnumerable;if(values==null||row[key] is string)return new[]{Convert.ToString(row[key])};return values.Cast<object>().Select(Convert.ToString).ToArray();}
 async Task ValidateInstaller(){if(busy)return;busy=true;tabs.IsEnabled=false;foreach(var button in operationButtons)button.IsEnabled=false;progress.Visibility=Visibility.Visible;progress.IsIndeterminate=false;progress.Minimum=0;progress.Maximum=1;progress.Value=0;installerToken="";string draft=InstallerDraftJson();status.Text="Validating media, image, emulator and package dependencies…";try{var row=(await Task.Run(()=>Bridge("ValidateInstaller",new[]{draft}))).Single();if(draft!=InstallerDraftJson()){installerValidation.Text="Choices changed during validation. Validate again.";return;}if(Convert.ToBoolean(row["Valid"])){installerToken=Get(row,"Token");validatedDraft=draft;installerValidation.Text=InstallerValidationText(row);status.Text="Validation passed. Ready to run installation or apply settings.";}else{installerValidation.Text=InstallerValidationText(row);status.Text="Installer choices need attention. See Review & Install.";}}catch(Exception ex){installerValidation.Text="Validation failed: "+ReadableMessage(ex.Message);status.Text=installerValidation.Text;}finally{tabs.IsEnabled=true;busy=false;progress.Visibility=Visibility.Collapsed;foreach(var button in operationButtons)button.IsEnabled=true;}}
 async Task ApplyInstaller(){if(busy)return;if(installerToken==""||validatedDraft!=InstallerDraftJson())await ValidateInstaller();if(installerToken==""||validatedDraft!=InstallerDraftJson())return;if(MessageBox.Show(this,"Apply the validated choices to this installation's settings?\n\nA backup of existing settings and assigns will be saved. This does not start installation or modify the Amiga image.","Apply installer configuration",MessageBoxButton.OKCancel,MessageBoxImage.Question)!=MessageBoxResult.OK)return;string draft=validatedDraft,token=installerToken;busy=true;tabs.IsEnabled=false;foreach(var button in operationButtons)button.IsEnabled=false;progress.Visibility=Visibility.Visible;progress.IsIndeterminate=false;progress.Minimum=0;progress.Maximum=1;progress.Value=0;try{var row=(await Task.Run(()=>Bridge("ApplyInstaller",new[]{draft,token}))).Single();installerValidation.Text="Settings applied to:\n"+Get(row,"SettingsPath")+"\n\nBackup saved to:\n"+Get(row,"Backup")+"\n\nUse Run installation on this tab to start.";status.Text="Installer settings saved. Installation has not started.";installerToken="";}catch(Exception ex){installerValidation.Text="Settings were not applied: "+ReadableMessage(ex.Message);status.Text=installerValidation.Text;installerToken="";}finally{tabs.IsEnabled=true;busy=false;progress.Visibility=Visibility.Collapsed;foreach(var button in operationButtons)button.IsEnabled=true;}}
 async Task RunInstallation(){if(busy)return;await ValidateInstaller();if(installerToken==""||validatedDraft!=InstallerDraftJson())return;if(MessageBox.Show(this,"Create a new image from the selected template and install into:\n\n"+plannedImageFolder+"\n\nExisting images will be preserved. Each run creates a separate folder.\n\nThe emulator will open and this app will track the result.","Run installation",MessageBoxButton.OKCancel,MessageBoxImage.Warning)!=MessageBoxResult.OK)return;string draft=validatedDraft,token=installerToken;busy=true;tabs.IsEnabled=false;foreach(var b in operationButtons)b.IsEnabled=false;progress.Visibility=Visibility.Visible;progress.IsIndeterminate=false;progress.Minimum=0;progress.Maximum=1;progress.Value=0;status.Text="Starting installation…";installerValidation.Text="Installation is running. The emulator will open when preparation finishes.";try{var row=(await Task.Run(()=>Bridge("RunInstaller",new[]{draft,token}))).Single();progress.Value=1;installerValidation.Text="Installation completed.\n\nNew image: "+Get(row,"ImageFolder")+"\n\nLog: "+Get(row,"Log")+"\nSettings backup: "+Get(row,"Backup");status.Text="Installation completed.";}catch(Exception ex){installerValidation.Text="Installation did not complete: "+ReadableMessage(ex.Message);status.Text=installerValidation.Text;}finally{installerToken="";plannedImageFolder="";tabs.IsEnabled=true;busy=false;progress.Visibility=Visibility.Collapsed;foreach(var b in operationButtons)b.IsEnabled=true;}}
 string ReadableMessage(string message){if(string.IsNullOrWhiteSpace(message))return "";if(System.Text.RegularExpressions.Regex.IsMatch(message,@"rate.?limit|too many requests|\b429\b",System.Text.RegularExpressions.RegexOptions.IgnoreCase))return "GitHub request limit reached. Saved releases can still be downloaded. Try checking again later.";string line=message.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Where(part=>!part.Contains("InitializeDefaultDrives")).FirstOrDefault()??"Operation failed.";line=System.Text.RegularExpressions.Regex.Replace(line,@"\s+"," ").Trim();return line.Length>260?line.Substring(0,257)+"…":line;}
 void ApplyRows(Dictionary<string,object>[] rows){foreach(var row in rows){string id=Get(row,"Id");var p=packages.FirstOrDefault(x=>x.Id==id);if(p==null){p=new Package{Category=Get(row,"Category"),Id=id,Name=Get(row,"Name"),PackageName=Get(row,"Package"),Url=Get(row,"Url"),Selected=selected.Contains(id)};p.PropertyChanged+=delegate{UpdateReview();Save();};packages.Add(p);}if(row.ContainsKey("Version")&&!string.IsNullOrWhiteSpace(Get(row,"Version")))p.Version=Get(row,"Version");if(row.ContainsKey("Available"))p.Available=Get(row,"Available");if(row.ContainsKey("Destination"))p.Destination=Get(row,"Destination");if(row.ContainsKey("Directory"))p.Directory=Get(row,"Directory");p.Status=Get(row,"Status");p.Details=ReadableMessage(Get(row,"Details"));string approval;p.ReviewDecision=approvals.TryGetValue(p.Id,out approval)&&approval==ReviewFingerprint(p)?"Approved for installation":"Not reviewed";p.Changed();}gameBundleCheck.DataContext=packages.FirstOrDefault(p=>p.Id=="gamepack/whdload-packs");}
 async Task Run(string action,string[] ids){if(busy)return;busy=true;foreach(var b in operationButtons)b.IsEnabled=false;progress.Visibility=Visibility.Visible;progress.IsIndeterminate=false;progress.Minimum=0;progress.Maximum=1;progress.Value=0;status.Text=action=="Catalog"?"Reading local catalog…":"Contacting official sources…";
 try{int failures=0,processed=0;bool githubLimited=false;if(action=="Catalog"){ApplyRows(await Task.Run(()=>Bridge(action,ids)));processed=packages.Count;}else{var targets=ids??new string[0];if(targets.Length==0){status.Text="No entries to process.";return;}progress.Minimum=0;progress.Maximum=targets.Length;for(int i=0;i<targets.Length;i++){var id=targets[i];var item=packages.FirstOrDefault(p=>p.Id==id);status.Text=(action=="ScanLocal"?"Scanning local versions":action=="DownloadPackages"?"Downloading":action=="Update"?"Updating":"Checking")+" "+(i+1)+" of "+targets.Length+": "+(item==null?id:item.Name)+"…";progress.IsIndeterminate=false;progress.Value=i;if(githubLimited && item!=null && item.Url!=null && item.Url.StartsWith("https://github.com/",StringComparison.OrdinalIgnoreCase)){item.Status="Check postponed";item.Details="GitHub request limit reached. Saved releases can still be downloaded. Try checking again later.";item.Changed();failures++;progress.Value=i+1;continue;}try{var rows=await Task.Run(()=>Bridge(action,new[]{id}));ApplyRows(rows);RememberScan("Packages",root,rows.Where(r=>Get(r,"Category")=="Packages").ToArray(),true);RememberScan("UserPackages",userPackagesFolder,rows.Where(r=>Get(r,"Category")=="User Packages").ToArray(),true);if((action=="CheckPackages"||action=="Check")&&rows.Any(r=>ReadableMessage(Get(r,"Details")).StartsWith("GitHub request limit",StringComparison.Ordinal)))githubLimited=true;processed+=rows.Length;failures+=rows.Count(r=>Get(r,"Status").Contains("failed")||Get(r,"Status")=="Review required"||Get(r,"Status")=="Check unavailable");}catch(Exception ex){failures++;if(item!=null){item.Status="Operation failed";item.Details=ReadableMessage(ex.Message);item.Changed();}}progress.Value=i+1;}}status.Text="Finished: "+processed+" entries processed"+(failures>0?"; "+failures+" need attention. See Status and Details.":".");UpdateReview();}catch(Exception ex){status.Text="Operation failed: "+ex.Message;}finally{progress.IsIndeterminate=false;progress.Visibility=Visibility.Collapsed;busy=false;foreach(var b in operationButtons)b.IsEnabled=true;}}
 async Task LoadMediaChoices(){try{mediaRows=(await Task.Run(()=>Bridge("MediaCatalog",null))).ToList();SetMediaChoices();RefreshMedia();}catch(Exception ex){mediaSummary.Text="Could not load media choices: "+ex.Message;}}
 string OsLabel(){return osSet=="Amiga OS 3.2"&&!string.IsNullOrEmpty(targetVersion)?"Amiga OS "+targetVersion:osSet;}
 string[] OsOptions(){var options=mediaRows.Where(r=>Get(r,"Kind")=="AmigaOS").Select(r=>Get(r,"Set")).Distinct().ToList();var manifest=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"data","release-manifest.json")));foreach(Dictionary<string,object> release in (System.Collections.IEnumerable)manifest["Releases"]){string label="Amiga OS "+Get(release,"Version");if(!options.Contains(label))options.Add(label);}return options.OrderBy(x=>x).ToArray();}
 void SetMediaChoices(){string wantedOs=osSet,wantedRom=kickstartSet,wantedTarget=targetVersion;string label=OsLabel();osChoice.ItemsSource=OsOptions();kickstartChoice.ItemsSource=mediaRows.Where(r=>Get(r,"Kind")=="Kickstart").Select(r=>Get(r,"Set")).Distinct().OrderBy(x=>x).ToArray();osChoice.SelectedItem=label;kickstartChoice.SelectedItem=wantedRom;osSet=wantedOs;kickstartSet=wantedRom;targetVersion=wantedTarget;UpdateMediaSelection();}
 void UpdateMediaSelection(){var parts=new List<string>();foreach(var pair in new[]{new[]{"AmigaOS",osSet},new[]{"Kickstart",kickstartSet}}){if(string.IsNullOrEmpty(pair[1])){parts.Add(pair[0]+": choose a set.");continue;}var entries=mediaRows.Where(r=>Get(r,"Kind")==pair[0]&&Get(r,"Set")==pair[1]).ToArray();parts.Add(pair[1]+": "+entries.Count(r=>Get(r,"Status")=="Detected")+" / "+entries.Length+" entries detected.");}selectionSummary.Text=(targetVersion!=""?"Target: AmigaOS "+targetVersion+". ":"")+string.Join("  ",parts)+" Selections are saved in your desktop draft. The table continues to show all sets.";}
 async Task RefreshEmulators(){try{string path=emulatorFile.Text;var rows=await Task.Run(()=>Bridge("Emulators",string.IsNullOrEmpty(path)?null:new[]{path}));var choices=rows.Select(r=>new ImageChoice{Name=Get(r,"Name"),Path=Get(r,"Path")}).ToList();if(choices.Count==0)choices.Add(new ImageChoice{Name="No installed emulators found — use Choose emulator…",Path=""});emulatorChoice.ItemsSource=choices;emulatorChoice.SelectedItem=choices.FirstOrDefault(c=>c.Path.Equals(path,StringComparison.OrdinalIgnoreCase));if(emulatorChoice.SelectedItem==null)emulatorChoice.SelectedIndex=0;}catch(Exception ex){status.Text="Emulator discovery failed: "+ex.Message;}}
 string Get(Dictionary<string,object> r,string key){return r.ContainsKey(key)?Convert.ToString(r[key]):"";}
 Dictionary<string,object>[] Bridge(string action,string[] ids){string temp=null;string progressFile=Path.GetTempFileName();try{if(ids!=null){temp=Path.GetTempFileName();File.WriteAllText(temp,json.Serialize(ids));}var info=new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -NonInteractive -File \""+Path.Combine(root,"desktop","bridge.ps1")+"\" -Action "+action+(temp==null?"":" -RequestFile \""+temp+"\"")){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=System.Text.Encoding.UTF8};info.EnvironmentVariables["HSTWB_DESKTOP_PROGRESS"]=progressFile;using(var p=Process.Start(info)){var errors=p.StandardError.ReadToEndAsync();var outputTask=p.StandardOutput.ReadToEndAsync();string lastProgress="";double completedItems=0;Dispatcher.Invoke(new Action(delegate{completedItems=Math.Floor(progress.Value);}));while(!p.WaitForExit(150)){try{string report=File.ReadAllText(progressFile);if(report.Length>0&&report!=lastProgress){var data=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(report);double fraction=Math.Max(0,Math.Min(0.99,Convert.ToDouble(data["Percent"])/100));string message=Convert.ToString(data["Message"]);lastProgress=report;Dispatcher.Invoke(new Action(delegate{if(!busy)return;progress.Value=Math.Min(progress.Maximum,completedItems+fraction);status.Text=message;}));}}catch{}}string output=outputTask.Result;if(p.ExitCode!=0){try{File.AppendAllText(Path.Combine(root,".output","desktop","bridge-errors.log"),DateTime.UtcNow.ToString("o")+" "+action+"\n"+errors.Result+"\n");}catch{}throw new Exception(ReadableMessage(errors.Result));}return json.Deserialize<Dictionary<string,object>[]>(output);}}finally{if(temp!=null)File.Delete(temp);File.Delete(progressFile);}}
 void UpdateReview(){review.Text="Installer mode: Install\nUser-package library: "+userPackagesFolder+"\nWHDLoad packs: "+gameFolder.Text+"\nImage folder: "+imageFolder.Text+"\nMedia folder: "+mediaFolder.Text+"\nEmulator: "+emulatorFile.Text+"\n\nAmigaOS: "+(string.IsNullOrEmpty(osSet)?"Not selected":OsLabel())+"\nKickstart: "+(string.IsNullOrEmpty(kickstartSet)?"Not selected":kickstartSet)+"\n\nInstallation draft — "+packages.Count(p=>p.Selected)+" components selected\n\n"+string.Join("\n",packages.Where(p=>p.Selected).Select(p=>"["+p.Category+"] "+p.Name+"  "+p.Version));}
 Dictionary<string,object> SettingsSnapshot(){return new Dictionary<string,object>{{"Format","HstWB.DesktopProfile"},{"SchemaVersion",1},{"Theme",theme.SelectedIndex},{"Brightness",brightness.SelectedIndex},{"UserPackagesFolder",userPackagesFolder},{"GamePacksFolder",gameFolder.Text},{"MediaFolder",mediaFolder.Text},{"OsSet",osSet},{"TargetVersion",targetVersion},{"KickstartSet",kickstartSet},{"ImageFolder",imageFolder.Text},{"EmulatorFile",emulatorFile.Text},{"ImageMode",imageMode.SelectedIndex},{"ImageTemplate",imageTemplate.SelectedItem==null?"":((ImageChoice)imageTemplate.SelectedItem).Path},{"Selected",selected.Where(id=>!packages.Any(p=>p.Id==id)).Concat(packages.Where(p=>p.Selected).Select(p=>p.Id)).Distinct().ToArray()},{"Approvals",approvals}};}
 void WriteSettings(string path,Dictionary<string,object> settings){string directory=Path.GetDirectoryName(Path.GetFullPath(path));System.IO.Directory.CreateDirectory(directory);string temporary=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temporary,json.Serialize(settings));if(File.Exists(path))File.Replace(temporary,path,path+".previous");else File.Move(temporary,path);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
 void Save(){if(loading)return;UpdateReview();if(installerToken!=""&&validatedDraft!=InstallerDraftJson()){installerToken="";installerValidation.Text="Choices changed. Validate installer choices again before applying.";}try{WriteSettings(statePath,SettingsSnapshot());}catch(Exception ex){status.Text="Could not save preferences: "+ex.Message;}}
 void SaveSettingsFile(){if(busy)return;var dialog=new Microsoft.Win32.SaveFileDialog{Title="Save desktop settings",Filter="HstWB desktop settings (*.hstwb-desktop.json)|*.hstwb-desktop.json",DefaultExt=".hstwb-desktop.json",FileName="My Amiga setup"};if(dialog.ShowDialog(this)!=true)return;try{WriteSettings(dialog.FileName,SettingsSnapshot());status.Text="Settings saved: "+dialog.FileName;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not save settings");}}
 void ValidateSettingsData(Dictionary<string,object> data){foreach(string key in new[]{"Theme","Brightness","ImageMode"})if(data.ContainsKey(key)&&(Convert.ToInt32(data[key])<0||Convert.ToInt32(data[key])>1))throw new Exception("Invalid "+key+" setting.");foreach(string key in new[]{"UserPackagesFolder","GamePacksFolder","MediaFolder","OsSet","TargetVersion","KickstartSet","ImageFolder","EmulatorFile","ImageTemplate"})if(data.ContainsKey(key)&&data[key]!=null&&!(data[key] is string))throw new Exception("Invalid "+key+" setting.");if(data.ContainsKey("GamePacksFolder")&&!string.IsNullOrEmpty(Get(data,"GamePacksFolder"))&&data.ContainsKey("UserPackagesFolder")&&!string.IsNullOrEmpty(Get(data,"UserPackagesFolder"))){string parent=Path.GetDirectoryName(Path.GetFullPath(Get(data,"GamePacksFolder")).TrimEnd(Path.DirectorySeparatorChar));if(!parent.Equals(Path.GetFullPath(Get(data,"UserPackagesFolder")).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new Exception("The WHDLoad Packs folder must belong to the selected user-package library.");}if(data.ContainsKey("ImageTemplate"))Path.GetFileName(Get(data,"ImageTemplate"));if(data.ContainsKey("Selected")){if(!(data["Selected"] is System.Collections.IEnumerable)||data["Selected"] is string)throw new Exception("Invalid package selections.");foreach(var id in (System.Collections.IEnumerable)data["Selected"])if(!(id is string))throw new Exception("Invalid package selection.");}if(data.ContainsKey("TargetVersion")&&!string.IsNullOrEmpty(Convert.ToString(data["TargetVersion"]))){string target=Convert.ToString(data["TargetVersion"]);if(!OsOptions().Contains("Amiga OS "+target))throw new Exception("Unsupported OS target version: "+target);}}
 void ApplySettingsData(Dictionary<string,object> data){ValidateSettingsData(data);bool previousLoading=loading;loading=true;try{if(data.ContainsKey("Theme"))theme.SelectedIndex=Convert.ToInt32(data["Theme"]);if(data.ContainsKey("Brightness"))brightness.SelectedIndex=Convert.ToInt32(data["Brightness"]);if(data.ContainsKey("UserPackagesFolder")&&!string.IsNullOrWhiteSpace(Get(data,"UserPackagesFolder")))userPackagesFolder=Get(data,"UserPackagesFolder");gameFolder.Text=data.ContainsKey("GamePacksFolder")&&!string.IsNullOrEmpty(Get(data,"GamePacksFolder"))?Get(data,"GamePacksFolder"):Path.Combine(userPackagesFolder,"WHDLoad Packs");if(!data.ContainsKey("UserPackagesFolder")&&data.ContainsKey("GamePacksFolder")&&!string.IsNullOrEmpty(Get(data,"GamePacksFolder")))userPackagesFolder=Path.GetDirectoryName(Path.GetFullPath(gameFolder.Text).TrimEnd(Path.DirectorySeparatorChar));userLibraryLabel.Text="Library: "+userPackagesFolder;mediaFolder.Text=Get(data,"MediaFolder");osSet=Get(data,"OsSet");targetVersion=Get(data,"TargetVersion");kickstartSet=Get(data,"KickstartSet");imageFolder.Text=Get(data,"ImageFolder");emulatorFile.Text=Get(data,"EmulatorFile");imageMode.SelectedIndex=data.ContainsKey("ImageMode")?Convert.ToInt32(data["ImageMode"]):0;string template=Get(data,"ImageTemplate");if(template!="")imageTemplate.SelectedItem=imageChoices.FirstOrDefault(c=>c.Path==template||Path.GetFileName(c.Path)==Path.GetFileName(template));selected.Clear();if(data.ContainsKey("Selected"))foreach(string id in (System.Collections.IEnumerable)data["Selected"])selected.Add(id);approvals.Clear();if(data.ContainsKey("Approvals")){var saved=data["Approvals"] as Dictionary<string,object>;if(saved!=null)foreach(var entry in saved)approvals[entry.Key]=Convert.ToString(entry.Value);}foreach(var p in packages){p.Selected=selected.Contains(p.Id);string approval;p.ReviewDecision=approvals.TryGetValue(p.Id,out approval)&&approval==ReviewFingerprint(p)?"Approved for installation":"Not reviewed";p.Changed();}SetMediaChoices();mediaRows=mediaRows.Select(r=>{var copy=new Dictionary<string,object>(r);copy["File"]="";copy["Status"]="Not scanned";copy["Match"]="";return copy;}).ToList();RefreshMedia();mediaSummary.Text="Settings loaded. Scan the saved media folder to refresh detection.";RestoreMediaScan();approvedImageFolder="";UpdateReview();ApplyTheme();}finally{loading=previousLoading;}}
 async Task LoadSettingsFile(){if(busy)return;var dialog=new Microsoft.Win32.OpenFileDialog{Title="Load desktop or existing installer settings",Filter="HstWB settings (*.json;*.ini)|*.json;*.ini|All files (*.*)|*.*",CheckFileExists=true};if(dialog.ShowDialog(this)!=true)return;busy=true;foreach(var button in operationButtons)button.IsEnabled=false;progress.Visibility=Visibility.Visible;progress.IsIndeterminate=false;progress.Minimum=0;progress.Maximum=1;progress.Value=0;try{Dictionary<string,object> data=null;if(Path.GetExtension(dialog.FileName).Equals(".json",StringComparison.OrdinalIgnoreCase)){var candidate=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(dialog.FileName));if(Get(candidate,"Format")=="HstWB.DesktopProfile"){if(!candidate.ContainsKey("SchemaVersion")||Convert.ToInt32(candidate["SchemaVersion"])!=1)throw new Exception("Unsupported desktop settings version.");data=candidate;}}if(data==null){var imported=await Task.Run(()=>Bridge("LoadSettings",new[]{dialog.FileName}));data=imported.Single();}ValidateSettingsData(data);WriteSettings(Path.Combine(root,"settings","before-load-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")+".hstwb-desktop.json"),SettingsSnapshot());ApplySettingsData(data);Save();ApplyRows(await Task.Run(()=>Bridge("Catalog",null)));RestorePackageScans();string selectedPacks=gameFolder.Text;ApplyGameInventory(await Task.Run(()=>Bridge("GamePacks",new[]{selectedPacks})));await RefreshEmulators();status.Text="Settings loaded into desktop draft. Review paths and media before installation.";}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not load settings");}finally{busy=false;progress.Visibility=Visibility.Collapsed;foreach(var button in operationButtons)button.IsEnabled=true;}}
 string ReviewFingerprint(Package p){return p.Version+"|"+p.Url+"|"+p.Directory+"|"+p.Destination;}
 string ReviewExplanation(Package p){if(p.Status=="Manual updates only")return "This bundle has no automatic update adapter. Review its source and installed files; newer bundles need manual integration.";if(p.Status=="Local version unverified")return "The local file does not match the expected checksum. Review your changes or restore a known package before automatic updating.";if(p.Status=="Source check failed"||p.Available=="Not verified")return "The upstream version could not be verified. Read the source error below, open the official page, and retry the check. An installation approval does not verify the update.";if(p.Status=="Compatibility review required")return "The newer release needs a compatibility review of its archive and installer. The existing adapter does not permit automatic replacement.";return "Review the source, version, destination and notes. You may approve this local package for your installation draft.";}
 void ShowPackageReview(Package p){var dialog=new Window{Owner=this,Title="Review — "+p.Name,Width=680,Height=560,MinWidth=520,MinHeight=420,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(20)};dialog.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(new TextBlock{Text=p.Name,FontSize=23,FontWeight=FontWeights.Bold});panel.Children.Add(new TextBlock{Text="Local: "+p.Version+"\nAvailable: "+p.Available+"\nStatus: "+p.Status+"\nAmiga destination: "+p.Destination+"\nLocal PC folder: "+p.Directory+"\nSource: "+p.Url,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,12)});panel.Children.Add(new TextBlock{Text=ReviewExplanation(p)+"\n\n"+p.Details,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,16)});panel.Children.Add(new TextBlock{Text="Approval records your installation choice. It does not bypass source, checksum, or compatibility checks for updates.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,16)});var actions=new WrapPanel();panel.Children.Add(actions);actions.Children.Add(Button("Open source webpage",delegate{OpenLink(new Button{Tag=p.Url},new RoutedEventArgs());}));actions.Children.Add(Button("Open local folder",delegate{if(System.IO.Directory.Exists(p.Directory))Process.Start(new ProcessStartInfo(p.Directory){UseShellExecute=true});}));actions.Children.Add(Button("Recheck source",async delegate{dialog.Close();await Run("Check",new[]{p.Id});}));var approve=Button("Approve for installation",delegate{approvals[p.Id]=ReviewFingerprint(p);p.ReviewDecision="Approved for installation";p.Selected=true;p.Changed();Save();dialog.Close();});approve.IsEnabled=p.Status!="Missing"&&System.IO.Directory.Exists(p.Directory);actions.Children.Add(approve);actions.Children.Add(Button("Close",delegate{dialog.Close();}));dialog.ShowDialog();}
 void ApplyTheme(){bool dark=brightness.SelectedIndex==1,classic=theme.SelectedIndex==0;var bg=(Color)ColorConverter.ConvertFromString(dark?"#20242C":classic?"#0055AA":"#AAAAAA");var surface=(Color)ColorConverter.ConvertFromString(dark?"#303641":classic?"#FFFFFF":"#DDDDDD");var fg=dark?Colors.White:Colors.Black;Background=new SolidColorBrush(bg);Foreground=new SolidColorBrush(dark||classic?Colors.White:Colors.Black);((Panel)Content).Background=Background;System.Windows.Documents.TextElement.SetForeground((DependencyObject)Content,Foreground);Resources["SurfaceText"]=new SolidColorBrush(fg);Resources["Accent"]=new SolidColorBrush(dark?Color.FromRgb(125,195,255):Color.FromRgb(0,55,135));
 foreach(var type in new[]{typeof(Button),typeof(TabItem),typeof(TextBox),typeof(DataGrid),typeof(DataGridCell),typeof(DataGridColumnHeader),typeof(ComboBox),typeof(ComboBoxItem)}){var style=new Style(type);style.Setters.Add(new Setter(Control.BackgroundProperty,new SolidColorBrush(surface)));style.Setters.Add(new Setter(Control.ForegroundProperty,new SolidColorBrush(fg)));Resources[type]=style;}var tabStyle=new Style(typeof(TabControl));tabStyle.Setters.Add(new Setter(Control.BackgroundProperty,new SolidColorBrush(surface)));tabStyle.Setters.Add(new Setter(Control.ForegroundProperty,new SolidColorBrush(fg)));Resources[typeof(TabControl)]=tabStyle;var headerStyle=new Style(typeof(DataGridColumnHeader));headerStyle.Setters.Add(new Setter(Control.BackgroundProperty,new SolidColorBrush(surface)));headerStyle.Setters.Add(new Setter(Control.ForegroundProperty,new SolidColorBrush(fg)));headerStyle.Setters.Add(new Setter(Control.BorderBrushProperty,dark?Brushes.LightSlateGray:Brushes.DimGray));headerStyle.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(0,0,1,2)));headerStyle.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(5,7,5,7)));headerStyle.Setters.Add(new Setter(Control.FontWeightProperty,FontWeights.SemiBold));Resources[typeof(DataGridColumnHeader)]=headerStyle;var labels=new Style(typeof(Label));labels.Setters.Add(new Setter(Control.ForegroundProperty,Foreground));Resources[typeof(Label)]=labels;var comboStyle=new Style(typeof(ComboBox));comboStyle.Setters.Add(new Setter(Control.ForegroundProperty,Brushes.Black));var comboText=new FrameworkElementFactory(typeof(TextBlock));comboText.SetBinding(TextBlock.TextProperty,new Binding());comboText.SetValue(TextBlock.ForegroundProperty,Brushes.Black);comboStyle.Setters.Add(new Setter(ItemsControl.ItemTemplateProperty,new DataTemplate{VisualTree=comboText}));Resources[typeof(ComboBox)]=comboStyle;var comboItemStyle=new Style(typeof(ComboBoxItem));comboItemStyle.Setters.Add(new Setter(Control.BackgroundProperty,Brushes.White));comboItemStyle.Setters.Add(new Setter(Control.ForegroundProperty,Brushes.Black));Resources[typeof(ComboBoxItem)]=comboItemStyle;var itemStyle=new Style(typeof(TabItem),(Style)Resources[typeof(TabItem)]);var selectedTrigger=new Trigger{Property=TabItem.IsSelectedProperty,Value=true};selectedTrigger.Setters.Add(new Setter(Control.ForegroundProperty,Brushes.Black));itemStyle.Triggers.Add(selectedTrigger);Resources[typeof(TabItem)]=itemStyle;
 }
 [STAThread]public static void Main(string[] args){try{var app=new Application();string appRoot=args.Length>0?args[0]:AppDomain.CurrentDomain.BaseDirectory; if(args.Length==0){var candidate=new DirectoryInfo(appRoot);while(candidate!=null&&!File.Exists(Path.Combine(candidate.FullName,"desktop","bridge.ps1")))candidate=candidate.Parent;appRoot=candidate!=null?candidate.FullName:Environment.CurrentDirectory;}var window=new Desktop(appRoot);if(args.Length>1 && args[1]=="--smoke"){window.TestImageChoices();window.TestSelectorsAndVersions();var rows=window.Bridge("Catalog",null);if(rows.Length==0)throw new Exception("Catalog is empty");window.ApplyRows(rows);window.TestSettingsAndSorting();foreach(string category in new[]{"Packages","User Packages"}){if(!window.packages.Any(p=>p.Category==category))throw new Exception("Missing category: "+category);var tab=window.tabs.Items.Cast<TabItem>().First(t=>(string)t.Header==category);var panel=(DockPanel)tab.Content;var grid=panel.Children.OfType<DataGrid>().Single();if(grid.Items.Cast<Package>().Any(p=>p.Category!=category)||grid.Items.Count!=window.packages.Count(p=>p.Category==category))throw new Exception("Category isolation failed: "+category);}window.tabs.SelectedIndex=2;window.loading=true;for(int i=0;i<2;i++){window.theme.SelectedIndex=i;for(int j=0;j<2;j++){window.brightness.SelectedIndex=j;window.ApplyTheme();var visual=(FrameworkElement)window.Content;visual.Measure(new Size(1180,780));visual.Arrange(new Rect(0,0,1180,780));visual.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(1180,780,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(window.root,".output","desktop","theme-"+i+"-"+j+".png")))encoder.Save(stream);}}window.tabs.SelectedIndex=1;var imageVisual=(FrameworkElement)window.Content;imageVisual.Measure(new Size(1180,780));imageVisual.Arrange(new Rect(0,0,1180,780));imageVisual.UpdateLayout();var imageBitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(1180,780,96,96,PixelFormats.Pbgra32);imageBitmap.Render(imageVisual);var imageEncoder=new System.Windows.Media.Imaging.PngBitmapEncoder();imageEncoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(imageBitmap));using(var imageStream=File.Create(Path.Combine(window.root,".output","desktop","image-screen.png")))imageEncoder.Save(imageStream);window.tabs.SelectedIndex=0;window.progress.Visibility=Visibility.Visible;window.progress.IsIndeterminate=false;window.progress.Maximum=47;window.progress.Value=12;window.status.Text="Checking 13 of 47: application source…";var mediaVisual=(FrameworkElement)window.Content;mediaVisual.Measure(new Size(1180,780));mediaVisual.Arrange(new Rect(0,0,1180,780));mediaVisual.UpdateLayout();var mediaBitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(1180,780,96,96,PixelFormats.Pbgra32);mediaBitmap.Render(mediaVisual);var mediaEncoder=new System.Windows.Media.Imaging.PngBitmapEncoder();mediaEncoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(mediaBitmap));using(var mediaStream=File.Create(Path.Combine(window.root,".output","desktop","media-screen.png")))mediaEncoder.Save(mediaStream);window.TestScanMemory();window.TestCompactRows();window.TestNativeReview();window.TestGamesTab();File.WriteAllText(Path.Combine(window.root,".output","desktop","smoke.txt"),"PASS: "+rows.Length+" catalog components; image and selector checks passed; settings roundtrip, OS targets, sorting, approvals and versions passed; all four theme combinations rendered.");return;}if(args.Length>1&&args[1]=="--games")window.tabs.SelectedIndex=4;app.Run(window);}catch(Exception ex){if(args.Length>1 && args[1]=="--smoke"){File.WriteAllText(Path.Combine(args[0],".output","desktop","smoke-error.txt"),ex.ToString());Environment.Exit(1);}else MessageBox.Show(ex.ToString(),"HstWB desktop");}}
